/// -1 = no such mapping , else sector number ///

SInt16 iap_sector_map_addr (const void * const addr_flash) 
{
  UInt8 sector = 0 ;

  do
    {
      #define ENTRY      iap_sector_info_table [sector]
      #define ADDR_FLASH (UInt32) addr_flash

      if (ENTRY.addr_base <= ADDR_FLASH && ADDR_FLASH <= ENTRY.addr_last)
        {
          return sector ;
        }

      #undef  ADDR_FLASH
      #undef  ENTRY
    }
  while (++sector < IAP_NUM_SECTORS) ;

  return -1 ;
}

